WITH filtered AS (SELECT *, ROUND(quantity, 0) AS quantity_rounded FROM order_items WHERE product_id IS NOT NULL), latest AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity, id) = 1), latest_order_items AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_rounded DESC, id) AS rn FROM latest) x WHERE rn = 1), latest_order_items_2 AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_rounded DESC NULLS LAST, id) AS dedup_rank FROM latest_order_items QUALIFY dedup_rank = 1) SELECT order_id, COUNT(DISTINCT order_id) AS distinct_order_ids, COUNT(*) AS num_rows, BIT_OR(quantity) AS quantity_bit_or FROM latest_order_items_2 GROUP BY 1 ORDER BY distinct_order_ids NULLS LAST;
